def format_bytes(n):
    """Return a human-readable byte size string (e.g. '1.5 KB')."""
    if n < 1024:
        return f"{n} B"
    value = n / 1024
    if value < 1024:
        return f"{value:.1f} KB"
    value /= 1024
    if value < 1024:
        return f"{value:.1f} MB"
    value /= 1024
    return f"{value:.1f} GB"
